void TCheatCode::encode(const char* value)
{
    int i = 0;
    const int maximum = 199;
    for (;;) {
        int length = static_cast<int>(strlen(value));
        const int* limit = &maximum;
        if (length <= maximum)
            limit = &length;
        if (i >= *limit)
            break;

        if (isalpha(value[i]))
            m_code[i] = s_b[tolower(value[i]) - 'a'];
        else
            m_code[i] = value[i];
        i++;
    }
    m_code[i] = 0;
}

